        ]}/><span className=\"table-live\"><i/> Обновлено только что</span></div>

        <div className=\"table-toolbar\"><TextInput className=\"search\" size=\"l\" hasClear value={query} onUpdate={value => {setQuery(value); setPage(1);}} placeholder=\"Поиск по имени, email или компании\" startContent={<Icon data={Magnifier} size={17}/>} controlProps={{'aria-label': 'Поиск клиентов'}}/>
          <div className=\"toolbar-actions\"><Button size=\"l\" view=\"outlined\" selected={filtersOpen || extraFilterCount > 0} onClick={() => setFiltersOpen("'!filtersOpen)}><Icon data={Sliders} size={16}/> Фильтры {extraFilterCount > 0 && <span className="filter-count">{extraFilterCount}</span>}</Button>
          <DropdownMenu renderSwitcher={props => <Button {...props} size="l" view="outlined"><span className="columns-icon" aria-hidden="true">▥</span> Столбцы <Icon data={ChevronDown} size={12}/></Button>}
            items={columns.filter(c => !['"'name', 'actions'].includes(c.id)).map(c => ({text: c.name as string, iconStart: "'!hiddenColumns.includes(c.id) ? <Icon data={Check} size={14}/> : <span style={{width: 14}}/>, action: () => toggleColumn(c.id)}))}/></div>
        </div>

        {filtersOpen && <div className="expanded-filters"><Select size="m" aria-label="Фильтр по городу" label="Город:" value={[city]} onUpdate={value => {setCity(value[0]); setPage(1);}} options={[{value: '"'all', content: 'Любой'}, ...Array.from(new Set(clients.map(c => c.city))).sort().map(value => ({value, content: value}))]}/><Select size=\"m\" aria-label=\"Фильтр по дате добавления\" label=\"Добавлены:\" value={[month]} onUpdate={value => {setMonth(value[0]); setPage(1);}} options={[{value: 'all', content: 'За всё время'}, {value: '2026-11', content: 'Ноябрь 2026'}, {value: '2026-10', content: 'Октябрь 2026'}, {value: '2026-09', content: 'Сентябрь 2026'}]}/><Button view=\"flat-secondary\" size=\"m\" onClick={resetFilters}>Сбросить фильтры</Button></div>}

        {selected.length > 0 && <div className=\"selection-bar\"><span><strong>Выбрано: {selected.length}</strong><span className=\"selection-divider\">/</span>{filtered.length} в списке</span><div><Button size=\"s\" view=\"flat\" onClick={() => setSelected(prev => Array.from(new Set([...prev, ...filtered.map(c => c.id)])))}>Выбрать все найденные</Button><Button size=\"s\" view=\"outlined\" onClick={() => exportCsv()}><Icon data={ArrowDownToLine} size={14}/> Экспорт</Button><Button size=\"s\" view=\"flat\" onClick={() => setSelected([])} aria-label=\"Снять выделение\"><Icon data={Xmark} size={16}/></Button></div></div>}

        <div className=\"table-scroll\"><ClientTable className=\"client-table\" width=\"max\" verticalAlign=\"middle\" data={visible} columns={columns.filter(c => "'!hiddenColumns.includes(c.id))} getRowDescriptor={client => ({id: client.id, interactive: true})}
          selectedIds={selected} onSelectionChange={setSelected} sortState={sort} disableDataSorting onSortStateChange={value => {setSort(value); setPage(1);}} emptyMessage="Клиенты не найдены. Попробуйте изменить запрос или фильтры."/></div>
        {filtered.length === 0 && <div className="empty-actions"><Button view="outlined" onClick={resetFilters}>Сбросить поиск и фильтры</Button></div>}

        <div className="table-footer"><span className="results-count">Показано <strong>{filtered.length ? (currentPage - 1) * pageSize + 1 : 0}–{Math.min(currentPage * pageSize, filtered.length)}</strong> из <strong>{filtered.length}</strong></span><div className="pagination-area"><div className="page-size"><span>На странице</span><Select aria-label="Количество строк на странице" size="m" value={[String(pageSize)]} onUpdate={value => {setPageSize(Number(value[0])); setPage(1);}} options={[10, 20, 50].map(value => ({value: String(value), content: String(value)}))}/></div><Pagination page={currentPage} pageSize={pageSize} total={filtered.length} size="m" compact view="clear" onUpdate={(next, size) => {setPage(next); setPageSize(size);}}/></div></div>
      </section>

      <div className="page-footnote"><span><Icon data={CircleInfo} size={14}/> Нажмите на заголовок столбца, чтобы изменить сортировку.</span><span>Демонстрационные данные</span></div>
      <footer className="footer"><span className="footer-brand">orbit.</span><span>Больше порядка. Ближе к клиентам.</span><span className="footer-end">Сделано для вашей команды</span></footer>
    </main>

    {notice && <div className="notice" role="status"><Icon data={CircleCheck} size={18}/><span>{notice}</span><Button size="s" view="flat" onClick={() => setNotice('"'')} aria-label=\"Закрыть уведомление\"><Icon data={Xmark} size={14}/></Button></div>}

    <Modal open={dialog "'!== null} onClose={() => setDialog(null)} aria-label={dialog === '"'add' ? 'Добавить клиента' : 'Помощь'}>
      <div className=\"dialog\"><div className=\"dialog-heading\"><Text variant=\"header-2\">{dialog === 'add' ? 'Новый клиент' : 'Всё под рукой'}</Text><Button view=\"flat\" onClick={() => setDialog(null)} aria-label=\"Закрыть окно\"><Icon data={Xmark} size={18}/></Button></div>
        {dialog === 'add' ? <form onSubmit={addClient}><Text as=\"p\" color=\"secondary\" variant=\"body-2\">Начните знакомство — добавьте клиента в вашу базу.</Text>
          <label className=\"form-field\">Имя и фамилия<TextInput size=\"l\" autoFocus value={form.name} onUpdate={name => setForm({...form, name})} placeholder=\"Например, Анна Смирнова\" controlProps={{required: true}}/></label>
          <label className=\"form-field\">Email<TextInput size=\"l\" type=\"email\" value={form.email} onUpdate={email => setForm({...form, email})} placeholder=\"anna@company.ru\" controlProps={{required: true}}/></label>
          <label className=\"form-field\">Компания<TextInput size=\"l\" value={form.company} onUpdate={company => setForm({...form, company})} placeholder=\"Название компании\" controlProps={{required: true}}/></label>
          <div className=\"form-columns\"><label className=\"form-field\">Город<TextInput size=\"l\" value={form.city} onUpdate={cityValue => setForm({...form, city: cityValue})} controlProps={{required: true}}/></label><div className=\"form-field\"><span id=\"status-field-label\">Статус</span><Select size=\"l\" width=\"max\" aria-labelledby=\"status-field-label\" value={[form.status]} onUpdate={value => setForm({...form, status: value[0]})} options={Object.entries(statusLabels).map(([value, content]) => ({value, content}))}/></div></div>
          {formError && <Text as=\"p\" color=\"danger\" role=\"alert\">{formError}</Text>}<div className=\"dialog-actions\"><Button size=\"l\" view=\"outlined\" onClick={() => setDialog(null)}>Отмена</Button><Button size=\"l\" view=\"action\" type=\"submit\"><Icon data={Plus} size={16}/> Добавить клиента</Button></div>
        </form> : <div className=\"help-content\"><Text as=\"p\" variant=\"body-2\">Управляйте клиентской базой в одном пространстве.</Text><p>Нажмите на заголовок столбца для сортировки. Повторное нажатие меняет направление. Удерживайте Shift для сортировки по нескольким столбцам.</p><p>Чекбокс в заголовке выделяет текущую страницу. Выбранные строки сохраняются при переходах между страницами. Кнопка «Выбрать все найденные» выделяет весь результат поиска.</p><p>Экспорт сохраняет выбранных клиентов, а если выделения нет — весь отфильтрованный список. Данные демонстрационные; изменения действуют до перезагрузки страницы.</p><Button view=\"action\" size=\"l\" onClick={() => setDialog(null)}>Всё понятно</Button></div>}
      </div>
    </Modal>
    <Modal open={detail "'!== null} onClose={() => setDetail(null)} aria-label="Карточка клиента"><div className="dialog">{detail && <><div className="dialog-heading"><Text variant="header-2">Карточка клиента</Text><Button view="flat" onClick={() => setDetail(null)} aria-label="Закрыть карточку"><Icon data={Xmark} size={18}/></Button></div><div className="detail-name"><ClientAvatar client={detail}/><Text variant="header-1">{detail.name}</Text></div><dl className="detail-list"><dt>Email</dt><dd>{detail.email}</dd><dt>Компания</dt><dd>{detail.company}</dd><dt>Город</dt><dd>{detail.city}</dd><dt>Статус</dt><dd><Label theme={statusThemes[detail.status]}>{statusLabels[detail.status]}</Label></dd><dt>Дата добавления</dt><dd>{dateFormat.format(new Date(detail.created))}</dd><dt>Выручка</dt><dd>{money.format(detail.revenue)} ₽</dd></dl><Button view="outlined" size="l" onClick={() => exportCsv([detail.id])}><Icon data={ArrowDownToLine} size={16}/> Экспортировать клиента</Button></>}</div></Modal>
  </div>;
}
EOF'

args.command:
/bin/bash -lc "cat > src/App.css <<'EOF'
.g-root_theme_light,
.g-root_theme_dark {
  --g-color-base-brand: var(--g-color-text-warning-heavy);
  --g-color-base-brand-hover: var(--g-color-base-warning-heavy-hover);
  --g-color-base-selection: var(--g-color-base-warning-light);
  --g-color-base-selection-hover: var(--g-color-base-warning-light-hover);
  --g-color-line-brand: var(--g-color-text-warning-heavy);
  --g-color-text-brand: var(--g-color-text-warning-heavy);
  --g-color-text-brand-contrast: var(--g-color-text-light-primary);
  --g-color-text-link: var(--g-color-text-warning-heavy);
  --g-color-text-link-hover: var(--g-color-base-warning-heavy-hover);
  --g-color-line-focus: var(--g-color-line-brand);
}

* {box-sizing: border-box;}
body {margin: 0;}
button, input {font: inherit;}
.app {min-height: 100vh; background: var(--g-color-base-generic-ultralight); color: var(--g-color-text-primary);}
.topbar {height: 76px; padding: 0 var(--g-spacing-10); display: flex; align-items: center; gap: var(--g-spacing-4); background: var(--g-color-base-background); border-bottom: 1px solid var(--g-color-line-generic);}
.brand {display: flex; align-items: center; gap: var(--g-spacing-2); font: var(--g-text-header-2-font); font-weight: 750; letter-spacing: -1.1px; padding-right: var(--g-spacing-3);}
.brand-period {color: var(--g-color-text-brand);}
.brand-symbol {display: grid; grid-template-columns: repeat(2, 9px); gap: 3px; transform: rotate(-8deg); margin-right: var(--g-spacing-1);}
.brand-symbol i {width: 9px; height: 9px; background: var(--g-color-base-brand); border-radius: var(--g-border-radius-xs);}
.brand-symbol i:last-child {opacity: .45;}
.topbar-divider {height: 24px; width: 1px; background: var(--g-color-line-generic); flex-shrink: 0;}
.workspace-button {--g-button-text-color: var(--g-color-text-complementary);}
.workspace-letter {display: inline-flex; width: 24px; height: 24px; align-items: center; justify-content: center; margin-right: var(--g-spacing-2); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-s); font: var(--g-text-body-1-font); font-weight: 600; background: var(--g-color-base-generic-ultralight);}
.plan-label {letter-spacing: .5px;}
.topbar-right {margin-left: auto; display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-secondary);}
.notification-icon {position: relative; display: inline-flex;}
.notification-icon i {position: absolute; width: 5px; height: 5px; background: var(--g-color-base-brand); top: 0; right: 0; border-radius: var(--g-border-radius-xl); outline: 2px solid var(--g-color-base-background);}
.main {max-width: 1440px; margin: 0 auto; padding: var(--g-spacing-8) var(--g-spacing-10) 0;}
.breadcrumbs {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-secondary); font: var(--g-text-body-1-font); margin-bottom: var(--g-spacing-6);}
.breadcrumb-current {color: var(--g-color-text-complementary);}
.page-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-7);}
.heading-line {display: flex; align-items: center; gap: var(--g-spacing-3);}
.heading-line h1 {margin: 0; letter-spacing: -.8px;}
.total-badge {font: var(--g-text-body-2-font); color: var(--g-color-text-secondary); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-1) var(--g-spacing-2); background: var(--g-color-base-background);}
.page-heading p {margin: var(--g-spacing-2) 0 0;}
.page-actions {display: flex; align-items: center; gap: var(--g-spacing-3); flex-shrink: 0;}
.page-actions .g-button {--g-button-border-radius: var(--g-border-radius-l);}
.stats {display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-7);}
.stat-card {border: 1px solid var(--g-color-line-generic); background: var(--g-color-base-background); padding: var(--g-spacing-5) var(--g-spacing-6); border-radius: var(--g-border-radius-xl); display: flex; justify-content: space-between; gap: var(--g-spacing-3);}
.stat-content {min-width: 0;}
.stat-label {font: var(--g-text-body-2-font); color: var(--g-color-text-complementary);}
.stat-number {display: flex; align-items: center; gap: var(--g-spacing-3); margin: var(--g-spacing-2) 0 var(--g-spacing-1);}
.stat-number > .g-text {letter-spacing: -.7px;}
.stat-change {display: inline-flex; align-items: center; gap: var(--g-spacing-1); font: var(--g-text-caption-2-font); color: var(--g-color-text-positive); background: var(--g-color-base-positive-light); border-radius: var(--g-border-radius-s); padding: 2px var(--g-spacing-1);}
.stat-percent {font: var(--g-text-caption-2-font); color: var(--g-color-text-secondary);}
.stat-caption {font: var(--g-text-caption-2-font); color: var(--g-color-text-secondary);}
.stat-icon {width: 40px; height: 40px; display: flex; align-items: center; justify-content: center; border-radius: var(--g-border-radius-xl); flex-shrink: 0;}
.stat-icon-neutral {color: var(--g-color-text-secondary); background: var(--g-color-base-generic);}
.stat-icon-green {color: var(--g-color-text-positive); background: var(--g-color-base-positive-light);}
.stat-icon-orange {color: var(--g-color-text-warning-heavy); background: var(--g-color-base-warning-light);}
.new-badge {font: var(--g-text-caption-2-font); color: var(--g-color-text-secondary);}
.table-panel {background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); overflow: hidden;}
.table-tabs {padding: 0 var(--g-spacing-5); display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--g-color-line-generic); gap: var(--g-spacing-4);}
.tab-count {font: var(--g-text-caption-2-font); padding: 1px var(--g-spacing-1); border-radius: var(--g-border-radius-s); background: var(--g-color-base-generic); color: var(--g-color-text-secondary); margin-left: var(--g-spacing-1);}
.table-live {display: flex; align-items: center; gap: var(--g-spacing-2); font: var(--g-text-caption-2-font); color: var(--g-color-text-secondary); white-space: nowrap;}
.table-live i {width: 5px; height: 5px; border-radius: var(--g-border-radius-xl); background: var(--g-color-text-positive);}
.table-toolbar {display: flex; align-items: center; gap: var(--g-spacing-4); padding: var(--g-spacing-4) var(--g-spacing-5);}
.search {max-width: 370px; min-width: 0; --g-text-input-border-radius: var(--g-border-radius-l);}
.search .g-icon {color: var(--g-color-text-secondary); margin-left: var(--g-spacing-3); margin-right: var(--g-spacing-1);}
.toolbar-actions {margin-left: auto; display: flex; align-items: center; gap: var(--g-spacing-2); flex-shrink: 0;}
.columns-icon {font-size: 17px; line-height: 1; margin-right: var(--g-spacing-1);}
.filter-count {padding: 0 var(--g-spacing-1); background: var(--g-color-base-warning-light); color: var(--g-color-text-brand); border-radius: var(--g-border-radius-s);}
.expanded-filters {display: flex; align-items: center; gap: var(--g-spacing-3); flex-wrap: wrap; padding: 0 var(--g-spacing-5) var(--g-spacing-4);}
.selection-bar {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3); padding: var(--g-spacing-2) var(--g-spacing-5); background: var(--g-color-base-selection); font: var(--g-text-body-1-font);}
.selection-bar > div {display: flex; align-items: center; gap: var(--g-spacing-2);}
.selection-divider {margin: 0 var(--g-spacing-3); color: var(--g-color-text-hint);}
.table-scroll {max-width: 100%; overflow-x: auto;}
.client-table {min-width: 1020px;}
.client-table .client-cell {padding: var(--g-spacing-3) var(--g-spacing-3);}
/* Header fill/typography have no Table CSS API. Narrow internal-class customization, pinned to uikit 7.43.0. */
.client-table .g-table__head {background: var(--g-color-base-generic-ultralight); color: var(--g-color-text-secondary);}
.client-table .g-table__head .g-table__cell {font-weight: 450; padding-top: var(--g-spacing-3); padding-bottom: var(--g-spacing-3);}
.client-person {display: flex; align-items: center; gap: var(--g-spacing-3);}
.client-person .g-avatar {flex-shrink: 0;}
.person-copy {display: flex; flex-direction: column; gap: 2px; min-width: 0;}
.person-name {font: var(--g-text-body-1-font); font-weight: 550; color: var(--g-color-text-primary);}
.person-email {font: var(--g-text-caption-2-font); color: var(--g-color-text-secondary);}
.company-name {color: var(--g-color-text-complementary);}
.status-dot {display: inline-block; width: 5px; height: 5px; border-radius: var(--g-border-radius-xl); background: currentColor; vertical-align: middle; margin-left: 2px;}
.city-column, .date-column {color: var(--g-color-text-complementary);}
.money {font-variant-numeric: tabular-nums; font-weight: 500;}
.ruble {color: var(--g-color-text-secondary);}
.action-column {width: 30px;}
.action-column .g-button {--g-button-text-color: var(--g-color-text-secondary);}
.empty-actions {padding: var(--g-spacing-5); display: flex; justify-content: center;}
.table-footer {min-height: 76px; padding: var(--g-spacing-4) var(--g-spacing-5); border-top: 1px solid var(--g-color-line-generic); display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4);}
.results-count {font: var(--g-text-body-1-font); color: var(--g-color-text-secondary); white-space: nowrap;}
.results-count strong {font-weight: 500; color: var(--g-color-text-complementary);}
.pagination-area {display: flex; align-items: center; gap: var(--g-spacing-6);}
.page-size {display: flex; align-items: center; gap: var(--g-spacing-2); font: var(--g-text-body-1-font); color: var(--g-color-text-secondary); white-space: nowrap;}
.page-size .g-select {min-width: 65px;}
.page-footnote {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3); margin: var(--g-spacing-4) 0 var(--g-spacing-8); color: var(--g-color-text-secondary); font: var(--g-text-caption-2-font);}
.page-footnote > span:first-child {display: flex; align-items: center; gap: var(--g-spacing-2);}
.footer {display: flex; align-items: center; gap: var(--g-spacing-4); padding: var(--g-spacing-5) 0 var(--g-spacing-6); color: var(--g-color-text-secondary); font: var(--g-text-caption-2-font); border-top: 1px solid var(--g-color-line-generic);}
.footer-brand {color: var(--g-color-text-complementary); font: var(--g-text-subheader-2-font); font-weight: 650; letter-spacing: -.6px;}
.footer-end {margin-left: auto;}
.notice {position: fixed; bottom: var(--g-spacing-6); left: 50%; transform: translateX(-50%); max-width: calc(100% - 32px); display: flex; align-items: center; gap: var(--g-spacing-3); background: var(--g-color-base-float); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); box-shadow: 0 4px 24px var(--g-color-sfx-shadow); padding: var(--g-spacing-3) var(--g-spacing-4); z-index: 100; font: var(--g-text-body-1-font);}
.notice > .g-icon {color: var(--g-color-text-positive); flex-shrink: 0;}
.dialog {width: 480px; max-width: calc(100vw - 32px); padding: var(--g-spacing-7);}
.dialog-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-4);}
.dialog p {margin: 0 0 var(--g-spacing-5);}
.form-field {display: flex; flex-direction: column; gap: var(--g-spacing-2); margin-top: var(--g-spacing-4); font: var(--g-text-body-1-font);}
.form-columns {display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--g-spacing-4);}
.dialog-actions {display: flex; justify-content: flex-end; gap: var(--g-spacing-3); margin-top: var(--g-spacing-7);}
.help-content {font: var(--g-text-body-2-font); color: var(--g-color-text-complementary);}
.help-content p {line-height: 1.65;}
.detail-name {display: flex; align-items: center; gap: var(--g-spacing-3); margin-top: var(--g-spacing-6);}
.detail-list {display: grid; grid-template-columns: 1fr 1.5fr; gap: var(--g-spacing-4); margin: var(--g-spacing-6) 0 var(--g-spacing-7);}
.detail-list dt {color: var(--g-color-text-secondary);}
.detail-list dd {margin: 0; overflow-wrap: anywhere;}

@media (min-width: 1500px) {
  .main {padding-top: var(--g-spacing-10);}
  .topbar {padding-inline: max(var(--g-spacing-10), calc((100vw - 1360px) / 2));}
}
@media (max-width: 1100px) {
  .topbar {padding-inline: var(--g-spacing-6);}
  .main {padding-inline: var(--g-spacing-6);}
  .table-live {display: none;}
  .stat-card {padding: var(--g-spacing-4);}
  .stat-icon {width: 32px; height: 32px;}
  .stat-caption {font: var(--g-text-caption-1-font);}
  .pagination-area {gap: var(--g-spacing-3);}
}
@media (max-width: 760px) {
  .topbar {height: 64px; padding-inline: var(--g-spacing-4); gap: var(--g-spacing-2);}
  .topbar > .topbar-divider, .plan-label, .workspace-button {display: none;}
  .brand {padding-right: 0;}
  .topbar-right {gap: 0;}
  .main {padding: var(--g-spacing-5) var(--g-spacing-4) 0;}
  .breadcrumbs {margin-bottom: var(--g-spacing-5);}
  .page-heading {align-items: flex-start; flex-direction: column; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-5);}
  .page-actions {width: 100%;}
  .page-actions > .g-button:last-child {flex: 1;}
